create or replace function app.phase2_guard() returns trigger language plpgsql set search_path='' as $$ declare j jsonb:=to_jsonb(new); k text; begin
if j ? 'starts_at' and j->>'ends_at' is not null and (j->>'ends_at')::timestamptz<=(j->>'starts_at')::timestamptz then raise exception 'active_dates_invalid'; end if;
case tg_table_name
when 'on_call_shifts' then if new.ends_at-new.starts_at>interval '7 days' or new.draft_label<>'Draft — pending clinical sign-off' or not exists(select 1 from public.staff_members s join public.staff_role_assignments a on a.staff_member_id=s.id and a.org_id=s.org_id where s.id=new.clinician_id and s.org_id=new.org_id and s.active and a.active and a.role in ('therapist','pmhnp','physician')) then raise exception 'licensed_draft_shift_required'; end if;
when 'referrals' then if new.identity_confidence not in ('verified_source','public_unverified') or new.status not in ('submitted','contacted','enrolled','declined') or (new.dob_unknown and new.dob is not null) then raise exception 'referral_state_invalid'; end if;
when 'advocates' then if not exists(select 1 from public.accounts where id=new.account_id and org_id=new.org_id and kind='advocate') then raise exception 'advocate_account_required'; end if;
when 'advocate_links' then if not exists(select 1 from public.consent_records where id=new.consent_record_id and org_id=new.org_id and patient_id=new.patient_id and consent_type='advocate_release') then raise exception 'advocate_consent_link_required'; end if;
when 'identity_review_items' then if exists(select 1 from unnest(new.candidate_patient_ids) x where not exists(select 1 from public.patients p where p.id=x and p.org_id=new.org_id)) or exists(select 1 from unnest(new.candidate_referral_ids) x where not exists(select 1 from public.referrals p where p.id=x and p.org_id=new.org_id)) then raise exception 'candidate_org_invalid'; end if;
when 'staging_rows' then if jsonb_typeof(new.identity_fields)<>'object' or exists(select 1 from jsonb_object_keys(new.identity_fields) k where k not in ('first_name','last_name','dob','phone','email','referrer_name','referrer_email','release_date')) then raise exception 'referral_identity_fields_only'; end if;
when 'packet_documents' then if new.classification not in ('general','part2','sud_related','unclassified') or new.part2_tagged<>(new.classification<>'general') or new.document_type not in ('hra','reentry_plan','medication_list','roi') or new.storage_path is not null then raise exception 'packet_classification_or_storage_invalid'; end if;
when 'intake_packet_needs' then if new.need_kind not in ('housing','food','transportation','employment','benefits','legal','education','childcare','other') or new.state not in ('confirmed_still_needed','resolved','unknown') then raise exception 'need_invalid'; end if;
else null; end case;
if tg_table_name in ('referral_codes','signup_sessions') then foreach k in array array['code_hash','otp_hash','identity_hash'] loop if j ? k and j->>k is not null and j->>k !~ '^[a-f0-9]{64}$' then raise exception 'hash_required'; end if; end loop; end if;
if tg_table_name in ('packet_documents','intake_packet_needs','staging_imports') then if j->>'source' not in ('referral_form','partner_referral','pre_release_packet') or length(trim(j->>'source_ref'))=0 then raise exception 'packet_source_required'; end if; end if;
if tg_table_name in ('packet_documents','intake_packet_needs') then if j->>'source'='referral_form' then if j->>'source_ref'<>'referral:'||j->>'referral_id' then raise exception 'source_reference_required'; end if; elsif not exists(select 1 from public.staging_rows sr join public.staging_imports si on si.id=sr.import_id and si.org_id=sr.org_id where sr.referral_id=(j->>'referral_id')::uuid and sr.org_id=(j->>'org_id')::uuid and si.source=j->>'source' and si.source_ref=j->>'source_ref') then raise exception 'source_reference_required'; end if; end if;
if tg_table_name in ('signup_safety_scans','pre_chart_triage') and j->>'result_tier' not in ('none','amber','red') then raise exception 'safety_tier_invalid'; end if;
return new; end $$;